import { useWorkspaceStore } from "@/state/workspaceStore";
import { Switch } from "@/shared/components/Switch";
import "@/ui/theme.css";

export function Popup() {
  const enabled = useWorkspaceStore((s) => s.enabled);
  const setEnabled = useWorkspaceStore((s) => s.setEnabled);

  async function handleToggle(next: boolean) {
    setEnabled(next);
    // Apply immediately on the page the user is looking at.
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (tab?.id && tab.url?.includes("cses.fi")) {
      chrome.tabs.reload(tab.id);
    }
  }

  return (
    <div data-theme="dark" className="bg-bg-base p-4 text-fg">
      <div className="flex items-center justify-between gap-3">
        <h1 className="text-[14px] font-semibold">Leetify for CSES</h1>
        <Switch
          checked={enabled}
          onChange={handleToggle}
          label="Enable Leetify for CSES"
        />
      </div>
      <p className="mt-1.5 text-[12px] text-fg-muted">
        {enabled
          ? "Open any CSES problem to launch the workspace."
          : "Disabled — CSES pages show their normal layout."}
      </p>
    </div>
  );
}
